546	// ─────────────────────────────────────────────────────────────────────────────
547	// Deltas comparativos (genéricos: vendas, perdas, compras — qualquer base)
548	// ─────────────────────────────────────────────────────────────────────────────
549	
550	/**
551	 * Delta % de `current` vs uma base de referência qualquer (ontem, semana
552	 * passada, período anterior do filtro…). Retorna null quando a base é
553	 * ausente ou não positiva — sem base honesta, sem número inventado.
554	 */
555	export function relativeDelta(
556	  current: number,
557	  base: number | null | undefined,
558	): number | null {
559	  if (base == null || base <= 0) return null;
560	  return ((current - base) / base) * 100;
561	}
562	
563	/**
564	 * Delta % vs MESMO DIA da semana anterior — caso particular de
565	 * {@link relativeDelta}, mantido pelo nome de domínio (comparativo
566	 * SECUNDÁRIO desde a v3; o principal é vs dia anterior).
567	 */
568	export function weekOverWeekDelta(
569	  current: number,
570	  lastWeek: number | null | undefined,
571	): number | null {
572	  return relativeDelta(current, lastWeek);
573	}
574	
575	/**
576	 * Base PRÓ-RATEADA de QUALQUER dia de referência para deltas do canal LIVE:
577	 * `referenceDayTotal × businessDayFraction(now)` — o delta resultante compara
578	 * hoje (dia parcial) vs o MESMO PONTO do dia de referência (ontem, semana
579	 * passada…), assumindo distribuição intra-dia linear na janela (mesma fração
580	 * usada no pró-rata da meta, por consistência).
581	 *
582	 * Comparar dia parcial com dia completo inflava a queda de manhã.
583	 * Canal defasado (dia completo vs dia completo) NÃO usa esta função.
584	 *
585	 * Retorna null quando a base é ausente/não positiva ou antes da abertura
586	 * (fração 0 — não há ponto de comparação honesto).
587	 */
588	export function proRataDayBase(
589	  referenceDayTotal: number | null | undefined,
590	  now: Date,
591	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
592	): number | null {
593	  if (referenceDayTotal == null || referenceDayTotal <= 0) return null;
594	  const fraction = businessDayFraction(now, hours);
595	  if (fraction <= 0) return null;
596	  return referenceDayTotal * fraction;
597	}
598	
599	/**
600	 * Alias histórico de {@link proRataDayBase} com o dia de referência fixado
601	 * em "mesmo dia da semana passada" (nome da v1/v2 — mantido para não quebrar
602	 * a API existente).
603	 */
604	export function proRataLastWeekBase(
605	  lastWeek: number | null | undefined,
606	  now: Date,
607	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
608	): number | null {
609	  return proRataDayBase(lastWeek, now, hours);
610	}
