613	// RAG da loja
614	// ─────────────────────────────────────────────────────────────────────────────
615	
616	/** Entrada da classificação RAG de uma unidade. */
617	export interface StoreRagInput {
618	  /** Itens zerados em alerta (quantidade ≤ 0 com mínimo definido). */
619	  stockOutCount: number;
620	  /** Itens abaixo do mínimo (quantidade entre 0 exclusivo e o mínimo). */
621	  stockLowCount: number;
622	  /** % da meta pró-rata (apenas canal live; null = não avaliar). */
623	  pctMetaProRata: number | null;
624	  /** true quando a unidade tem venda ao vivo (canal Degust). */
625	  isLiveChannel: boolean;
626	  /** Última movimentação de estoque (ISO/Date), ou null se nenhuma hoje. */
627	  lastMovementAt: Date | string | null;
628	  /** Instante da avaliação. */
629	  now: Date;
630	  /** Janela de funcionamento (default lojas; fábrica usa TV_FACTORY_HOURS). */
631	  hours?: TvBusinessHours;
632	  /** Threshold de horas sem movimentação (default lojas 3h; fábrica 2h). */
633	  noMovementThresholdHours?: number;
634	}
635	
636	/**
637	 * Horas sem movimentação consideradas DENTRO da janela de funcionamento.
638	 *
639	 * - Fora da janela (antes de abrir / depois de fechar) retorna null —
640	 *   não faz sentido alertar madrugada sem bipagem.
641	 * - A referência é clampada ao início da janela de hoje: se a última
642	 *   movimentação foi ontem, o "relógio" só começa a contar na abertura.
643	 */
644	export function hoursWithoutMovementInWindow(
645	  lastMovementAt: Date | string | null,
646	  now: Date,
647	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
648	): number | null {
649	  const fraction = businessDayFraction(now, hours);
650	  if (fraction <= 0 || fraction >= 1) return null;
651	  const windowStart = new Date(now);
652	  windowStart.setHours(hours.start, 0, 0, 0);
653	  const last = lastMovementAt
654	    ? new Date(lastMovementAt).getTime()
655	    : Number.NEGATIVE_INFINITY;
656	  const ref = Math.max(last, windowStart.getTime());
657	  return (now.getTime() - ref) / 3_600_000;
658	}
659	
660	/**
661	 * Classificação RAG de uma unidade (management-by-exception).
662	 *
663	 * Regras (design.md §1.6, ordem de precedência):
664	 * - VERMELHO: SOMENTE ruptura — item zerado em alerta (`stockOutCount > 0`).
665	 *   Venda fraca NUNCA derruba o card pra vermelho (era falso-positivo de
666	 *   manhã, quando o pró-rata ainda é instável).
667	 * - ÂMBAR: itens abaixo do mínimo (`stockLowCount > 0`) OU unidade sem
668	 *   movimentação há mais que o threshold dentro da janela OU venda live com
669	 *   ratio pró-rata abaixo de {@link LIVE_SALES_AMBER_THRESHOLD_PCT}% —
670	 *   esta última SOMENTE a partir de {@link LIVE_SALES_AMBER_FROM_HOUR}h,
671	 *   em canal live e com meta cadastrada (pct != null).
672	 * - OK: nenhum desvio — tela calma, sem cor.
673	 */
674	export function classifyStoreRag(input: StoreRagInput): {
675	  status: TvRagStatus;
676	  reasons: string[];
677	} {
678	  const hours = input.hours ?? TV_BUSINESS_HOURS;
679	  const noMovementThreshold =
680	    input.noMovementThresholdHours ?? NO_MOVEMENT_THRESHOLD_HOURS;
681	  const reasons: string[] = [];
682	
683	  // ── Vermelho: só ruptura (item zerado em alerta) ──
684	  if (input.stockOutCount > 0) {
685	    reasons.push(
686	      `${input.stockOutCount} ${input.stockOutCount === 1 ? 'item zerado' : 'itens zerados'} em alerta`,
687	    );
688	    return { status: 'red', reasons };
689	  }
690	
691	  // ── Âmbar ──
692	  if (input.stockLowCount > 0) {
693	    reasons.push(
694	      `${input.stockLowCount} ${input.stockLowCount === 1 ? 'item abaixo' : 'itens abaixo'} do mínimo`,
695	    );
696	  }
697	  const gapHours = hoursWithoutMovementInWindow(
698	    input.lastMovementAt,
699	    input.now,
700	    hours,
701	  );
702	  if (gapHours !== null && gapHours > noMovementThreshold) {
703	    reasons.push(`sem movimentação há ${Math.floor(gapHours)}h`);
704	  }
705	  if (
706	    input.isLiveChannel &&
707	    input.pctMetaProRata !== null &&
708	    input.pctMetaProRata < LIVE_SALES_AMBER_THRESHOLD_PCT &&
709	    input.now.getHours() >= LIVE_SALES_AMBER_FROM_HOUR
710	  ) {
711	    reasons.push(
712	      `venda ao vivo em ${Math.round(input.pctMetaProRata)}% do esperado pró-rata`,
713	    );
714	  }
715	  if (reasons.length > 0) return { status: 'amber', reasons };
716	
717	  return { status: 'ok', reasons: [] };
718	}
719	
720	/** Entrada de {@link buildNoMovementException}. */
721	export interface NoMovementExceptionInput {
722	  lojaId: number;
723	  lojaNome: string;
724	  /** Timestamp da última movimentação (ISO/Date), ou null se nenhuma hoje. */
725	  lastMovementAt: Date | string | null;
726	  now: Date;
727	  /** Janela de funcionamento (default lojas; fábrica usa TV_FACTORY_HOURS). */
728	  hours?: TvBusinessHours;
729	  /** Threshold em horas (default lojas 3h; fábrica 2h). */
730	  thresholdHours?: number;
731	}
732	
733	/**
734	 * Exceção "sem movimentação" derivada DIRETO do dado estruturado (timestamp
735	 * da última bipagem + janela), nunca por parsing de string de ragReasons —
736	 * por isso INDEPENDE da cor do card (aparece mesmo com card vermelho) e
737	 * cobre também a fábrica (janela/threshold próprios via parâmetros).
738	 * Retorna null quando não há gap acima do threshold dentro da janela.
739	 */
740	export function buildNoMovementException(
741	  input: NoMovementExceptionInput,
742	): TvException | null {
743	  const threshold = input.thresholdHours ?? NO_MOVEMENT_THRESHOLD_HOURS;
744	  const gap = hoursWithoutMovementInWindow(
745	    input.lastMovementAt,
746	    input.now,
747	    input.hours ?? TV_BUSINESS_HOURS,
748	  );
749	  if (gap === null || gap <= threshold) return null;
750	  return {
751	    id: `no-movement:${input.lojaId}`,
752	    kind: 'no-movement',
753	    severity: 'amber',
754	    lojaId: input.lojaId,
755	    lojaNome: input.lojaNome,
756	    message: `${input.lojaNome} sem movimentação há ${Math.floor(gap)}h em horário comercial`,
757	  };
758	}
