760	// ─────────────────────────────────────────────────────────────────────────────
761	// Formatação compacta de moeda (tipografia de TV: "R$ 12,4k")
762	// ─────────────────────────────────────────────────────────────────────────────
763	
764	function trimOneDecimal(v: number): string {
765	  const rounded = Math.round(v * 10) / 10;
766	  return rounded.toLocaleString('pt-BR', {
767	    minimumFractionDigits: 0,
768	    maximumFractionDigits: 1,
769	  });
770	}
771	
772	/**
773	 * Formata um valor em BRL compacto para leitura a 3-5 metros:
774	 * 950 → "R$ 950" · 12.400 → "R$ 12,4k" · 1.250.000 → "R$ 1,3M".
775	 * Valores negativos preservam o sinal ("-R$ 1,2k").
776	 */
777	export function formatCompactBRL(value: number): string {
778	  const sign = value < 0 ? '-' : '';
779	  const abs = Math.abs(value);
780	  // Bump pra M quando o arredondamento em k chegaria a 1000k
781	  if (abs >= 1_000_000 || (abs >= 1_000 && Math.round(abs / 100) >= 10_000)) {
782	    return `${sign}R$ ${trimOneDecimal(abs / 1_000_000)}M`;
783	  }
784	  if (abs >= 1_000) {
785	    return `${sign}R$ ${trimOneDecimal(abs / 1_000)}k`;
786	  }
787	  return `${sign}R$ ${Math.round(abs).toLocaleString('pt-BR')}`;
788	}
789	
790	// ─────────────────────────────────────────────────────────────────────────────
791	// Staleness
792	// ─────────────────────────────────────────────────────────────────────────────
793	
794	/**
795	 * Classifica o frescor de um dado-fonte dado o intervalo esperado:
796	 * - `fresh`: idade abaixo de 2× o intervalo esperado (tolera um ciclo perdido).
797	 * - `stale`: idade entre 2× e 6× (âmbar na UI, conforme spec).
798	 * - `very-stale`: idade a partir de 6×, timestamp inválido ou ausente.
799	 */
800	export function classifyStaleness(
801	  lastUpdatedAt: Date | string | number | null | undefined,
802	  expectedIntervalMs: number,
803	  now: Date,
804	): TvFreshnessLevel {
805	  if (lastUpdatedAt == null) return 'very-stale';
806	  const ts = new Date(lastUpdatedAt).getTime();
807	  if (!Number.isFinite(ts) || ts <= 0) return 'very-stale';
808	  const age = now.getTime() - ts;
809	  if (age < 2 * expectedIntervalMs) return 'fresh';
810	  if (age < 6 * expectedIntervalMs) return 'stale';
811	  return 'very-stale';
812	}
813	
814	/**
815	 * Monta o freshness consolidado a partir dos timestamps CRUS de última
816	 * atualização bem-sucedida (React Query `dataUpdatedAt`, em ms; 0 = nunca).
817	 *
818	 * A classificação depende de `now`: o chamador DEVE reavaliar com um relógio
819	 * que AVANÇA (tick de minuto), para que um outage total — nenhuma query
820	 * devolvendo dado novo — escale o chip pra âmbar quando `dataUpdatedAt`
821	 * parar de avançar além de 2× o intervalo esperado.
822	 */
823	export function buildFreshness(
824	  liveUpdatedAtMs: number,
825	  stockUpdatedAtMs: number,
826	  intervals: { liveMs: number; slowMs: number },
827	  now: Date,
828	): TvFreshness {
829	  const liveUpdatedAt =
830	    liveUpdatedAtMs > 0 ? new Date(liveUpdatedAtMs).toISOString() : null;
831	  const stockUpdatedAt =
832	    stockUpdatedAtMs > 0 ? new Date(stockUpdatedAtMs).toISOString() : null;
833	  return {
834	    vendasLive: {
835	      updatedAt: liveUpdatedAt,
836	      level: classifyStaleness(liveUpdatedAt, intervals.liveMs, now),
837	      expectedIntervalMs: intervals.liveMs,
838	    },
839	    estoque: {
840	      updatedAt: stockUpdatedAt,
841	      level: classifyStaleness(stockUpdatedAt, intervals.slowMs, now),
842	      expectedIntervalMs: intervals.slowMs,
843	    },
844	    geradoEm: now.toISOString(),
845	  };
846	}
847	
848	// ─────────────────────────────────────────────────────────────────────────────
849	// Exceções — ordenação e corte
850	// ─────────────────────────────────────────────────────────────────────────────
851	
852	const SEVERITY_ORDER: Record<string, number> = { red: 0, amber: 1 };
853	// design.md §6.1: rupturas → abaixo-do-mínimo → sem-bipagem → stale
854	const KIND_ORDER: Record<string, number> = {
855	  'stock-out': 0,
856	  'stock-low': 1,
857	  'no-movement': 2,
858	  'stale-data': 3,
859	};
860	
861	/**
862	 * Ordena exceções por severidade (vermelho antes de âmbar), depois por tipo
863	 * (falta total, abaixo do mínimo, sem movimentação, dado stale — nesta ordem,
864	 * design.md §6.1) e por mensagem (estável), limitando a `limit` linhas com
865	 * contagem do excedente.
866	 */
867	export function sortAndLimitExceptions(
868	  exceptions: TvException[],
869	  limit: number = TV_EXCEPTIONS_LIMIT,
870	): TvExceptionsResult {
871	  const sorted = [...exceptions].sort((a, b) => {
872	    const sev = (SEVERITY_ORDER[a.severity] ?? 9) - (SEVERITY_ORDER[b.severity] ?? 9);
873	    if (sev !== 0) return sev;
874	    const kind = (KIND_ORDER[a.kind] ?? 9) - (KIND_ORDER[b.kind] ?? 9);
875	    if (kind !== 0) return kind;
876	    return a.message.localeCompare(b.message, 'pt-BR');
877	  });
878	  return {
879	    items: sorted.slice(0, limit),
880	    overflowCount: Math.max(0, sorted.length - limit),
881	    totalCount: sorted.length,
882	  };
883	}
