1048	/**
1049	 * Corrige o `loja_id` das linhas de flash-vendas.
1050	 *
1051	 * LANDMINE conhecida: a edge function `degust-pos-financial` (deployada)
1052	 * só mapeia os códigos Degust 1→4 e 2→5; códigos não mapeados passam CRUS
1053	 * (ex.: BSB Shopping = código Degust 3 chega como `loja_id: 3`, colidindo
1054	 * com Asa Norte). Aqui remapeamos usando a tabela `degust_stores`
1055	 * (degust_loja_codigo → loja_id), que é a fonte de verdade em runtime.
1056	 *
1057	 * - Linha cujo loja_id já é uma loja Degust conhecida → mantém.
1058	 * - Linha cujo loja_id corresponde a um código Degust → remapeia.
1059	 * - Caso contrário → descarta (não corromper outra loja).
1060	 */
1061	export function remapFlashLojaIds(
1062	  rows: FlashRow[],
1063	  degustCodeToLoja: ReadonlyMap<number, number>,
1064	  knownDegustLojaIds: ReadonlySet<number>,
1065	): FlashRow[] {
1066	  const out: FlashRow[] = [];
1067	  for (const row of rows) {
1068	    if (knownDegustLojaIds.has(row.loja_id)) {
1069	      out.push(row);
1070	      continue;
1071	    }
1072	    const mapped = degustCodeToLoja.get(row.loja_id);
1073	    if (mapped != null) {
1074	      out.push({ ...row, loja_id: mapped });
1075	    }
1076	    // não mapeável → descartado de propósito (ver TSDoc)
1077	  }
1078	  return out;
1079	}
