1081	/**
1082	 * Converte os itens de alerta de uma unidade em estoque crítico NOMEADO,
1083	 * ordenado por severidade: zerados (⛔) primeiro, depois abaixo do mínimo
1084	 * (⚠) por % FALTANTE decrescente ((minima − quantidade) / minima); empate
1085	 * por nome (estável). Dentro dos zerados, quantidade mais negativa primeiro
1086	 * (mesma fração). A coluna exibe os {@link TV_CRITICAL_TOP_N} primeiros;
1087	 * o drill-down, a lista completa.
1088	 */
1089	export function sortCriticalItems(items: TvStockAlertItem[]): TvCriticalItem[] {
1090	  const missingFraction = (c: TvCriticalItem): number =>
1091	    c.minima > 0 ? (c.minima - c.quantidade) / c.minima : 0;
1092	  return items
1093	    .map<TvCriticalItem>((i) => ({
1094	      nome: i.produtoNome,
1095	      quantidade: i.quantidade,
1096	      minima: i.quantidadeMinima,
1097	      severity: i.zerado ? 'zerado' : 'abaixo-minimo',
1098	    }))
1099	    .sort((a, b) => {
1100	      if (a.severity !== b.severity) return a.severity === 'zerado' ? -1 : 1;
1101	      const diff = missingFraction(b) - missingFraction(a);
1102	      if (diff !== 0) return diff;
1103	      return a.nome.localeCompare(b.nome, 'pt-BR');
1104	    });
1105	}
