1237	// Paginação PostgREST (loop genérico com fetcher injetado — sem I/O próprio)
1238	// ─────────────────────────────────────────────────────────────────────────────
1239	
1240	/** Página de resultado mínima consumida por {@link fetchAllPages}. */
1241	export interface TvPageResult<T> {
1242	  data: T[] | null;
1243	  error: { message: string } | null;
1244	}
1245	
1246	/**
1247	 * Busca TODAS as linhas paginando com `.range()`: o PostgREST corta qualquer
1248	 * resposta em 1000 linhas mesmo com `.limit()` maior — truncamento SILENCIOSO
1249	 * (mesmo padrão de `features/producao/hooks/useProductionForecast`).
1250	 *
1251	 * Loop até a página vir menor que `pageSize`. O fetcher é injetado (esta
1252	 * função não faz I/O próprio — testável com mock) e DEVE aplicar ordenação
1253	 * estável (`.order` em coluna única, ex.: `id`) para as páginas não se
1254	 * sobreporem entre requests.
1255	 */
1256	export async function fetchAllPages<T>(
1257	  fetchPage: (from: number, to: number) => PromiseLike<TvPageResult<T>>,
1258	  pageSize = 1000,
1259	): Promise<T[]> {
1260	  const all: T[] = [];
1261	  let offset = 0;
1262	  for (;;) {
1263	    const { data, error } = await fetchPage(offset, offset + pageSize - 1);
1264	    if (error) throw error;
1265	    const rows = data ?? [];
1266	    all.push(...rows);
1267	    if (rows.length < pageSize) return all;
1268	    offset += pageSize;
1269	  }
1270	}
