// ─────────────────────────────────────────────────────────────────────────────
// Curva horária (R5) + projeção de fim de mês (R3)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Hora-limite da madrugada no DIA COMERCIAL: buckets 00h–05h pertencem ao
 * FIM do dia, não ao começo. O caixa do Degust agrupa por dataCaixa — uma
 * venda às 02:00 tem dataCaixa do dia anterior (é o fechamento da noite),
 * então na curva horária ela vem DEPOIS das 23h, nunca antes da manhã.
 *
 * NÃO usar {@link TV_BUSINESS_HOURS}.start (10h) como corte: a loja Lago
 * Sul é brunch e vende legitimamente às 08h–09h (byHour real com chaves
 * "08"/"09"). Lojas abrem no mínimo às 8h — 06h é um corte seguro.
 */
export const TV_OVERNIGHT_END_HOUR = 6;

/**
 * Rank de uma hora-calendário dentro do DIA COMERCIAL: madrugada (00–05)
 * desloca +24 para ordenar DEPOIS das 23h. Sequência resultante:
 * 06, 07, …, 23, 24 (=00h), 25 (=01h), …, 29 (=05h).
 */
export function businessHourRank(hour: number): number {
  return hour < TV_OVERNIGHT_END_HOUR ? hour + 24 : hour;
}

/**

input.old_string:
 * A curva é usada APENAS como fração (kits têm valorUnitario 0 na fonte) —
 * o valor absoluto vem sempre do total oficial `prevDayTotal`.
 *
 * Retorna null quando não há base honesta — curva ausente/vazia, cumulativo
 * total 0, total não positivo ou fração 0 (antes da 1ª venda do dia de
 * referência) — para o caller cair no fallback pró-rata linear existente.
 */
export function hourlyPaceBase(
  prevDayTotal: number,
  prevDayByHour: Record<string, number> | undefined,
  now: Date,
): number | null {
  if (prevDayTotal <= 0 || !prevDayByHour) return null;
  const buckets: Array<[number, number]> = [];
  for (const [hh, value] of Object.entries(prevDayByHour)) {
    const hour = Number(hh);
    if (!Number.isInteger(hour) || hour < 0 || hour > 23) continue;
    buckets.push([hour, value]);
  }
  const cumTotal = buckets.reduce((s, [, v]) => s + v, 0);
  if (cumTotal <= 0) return null;
  const currentHour = now.getHours();
  const minuteFraction = (now.getMinutes() + now.getSeconds() / 60) / 60;
  let cumNow = 0;
  for (const [hour, value] of buckets) {
    if (hour < currentHour) cumNow += value;
    else if (hour === currentHour) cumNow += value * minuteFraction;
  }
  if (cumNow <= 0) return null;
  return prevDayTotal * (cumNow / cumTotal);
}

input.new_string:
 * A curva é usada APENAS como fração (kits têm valorUnitario 0 na fonte) —
 * o valor absoluto vem sempre do total oficial `prevDayTotal`.
 *
 * O cumulativo segue a ordem do DIA COMERCIAL ({@link businessHourRank}):
 * buckets da madrugada (00h–05h, dataCaixa do dia anterior — fechamento da
 * noite) ordenam DEPOIS das 23h, e a hora corrente também é ranqueada —
 * às 00:30 o ponto de corte é 24,5 (fim do dia comercial corrente), não
 * 0,5. Sem isso, uma venda às 02h de ontem inflava a base da MANHÃ de hoje.
 *
 * Retorna null quando não há base honesta — curva ausente/vazia, cumulativo
 * total 0, total não positivo ou fração 0 (antes da 1ª venda do dia de
 * referência) — para o caller cair no fallback pró-rata linear existente.
 */
export function hourlyPaceBase(
  prevDayTotal: number,
  prevDayByHour: Record<string, number> | undefined,
  now: Date,
): number | null {
  if (prevDayTotal <= 0 || !prevDayByHour) return null;
  const buckets: Array<[number, number]> = [];
  for (const [hh, value] of Object.entries(prevDayByHour)) {
    const hour = Number(hh);
    if (!Number.isInteger(hour) || hour < 0 || hour > 23) continue;
    buckets.push([businessHourRank(hour), value]);
  }
  const cumTotal = buckets.reduce((s, [, v]) => s + v, 0);
  if (cumTotal <= 0) return null;
  const currentRank = businessHourRank(now.getHours());
  const minuteFraction = (now.getMinutes() + now.getSeconds() / 60) / 60;
  let cumNow = 0;
  for (const [rank, value] of buckets) {
    if (rank < currentRank) cumNow += value;
    else if (rank === currentRank) cumNow += value * minuteFraction;
  }
  if (cumNow <= 0) return null;
  return prevDayTotal * (cumNow / cumTotal);
}

