describe('businessHourRank (madrugada = fim do dia comercial)', () => {
  it('desloca 00h–05h para depois das 23h (dataCaixa do Degust)', () => {
    expect(businessHourRank(0)).toBe(24);
    expect(businessHourRank(2)).toBe(26);
    expect(businessHourRank(5)).toBe(29);
  });

  it('mantém horas diurnas/noturnas inalteradas a partir das 06h', () => {
    expect(businessHourRank(TV_OVERNIGHT_END_HOUR)).toBe(6);
    expect(businessHourRank(8)).toBe(8); // brunch Lago Sul vende 08h-09h
    expect(businessHourRank(23)).toBe(23);
  });
});

describe('hourlyPaceBase — madrugada pertence ao FIM do dia comercial', () => {
  // Curva de ontem COM venda na madrugada (cupom às 02h = fechamento da
  // noite, mesmo dataCaixa). Total 3500.
  const curveWithOvernight: Record<string, number> = {
    '02': 500,
    '10': 1_000,
    '14': 1_000,
    '20': 1_000,
  };

  it('às 11h NÃO conta a venda das 02h (rank 26, depois das 20h)', () => {
    const base = hourlyPaceBase(
      3_500,
      curveWithOvernight,
      new Date(2026, 5, 4, 11, 0, 0),
    );
    // Só o bucket "10" entrou: 1000/3500 — antes do fix dava 1500/3500
    expect(base).toBeCloseTo(3_500 * (1_000 / 3_500), 5);
  });

  it('às 23h inclui 10/14/20 mas ainda não a madrugada → 3000/3500', () => {
    const base = hourlyPaceBase(
      3_500,
      curveWithOvernight,
      new Date(2026, 5, 4, 23, 0, 0),
    );
    expect(base).toBeCloseTo(3_500 * (3_000 / 3_500), 5);
  });

  it('às 02:30 (now de madrugada, rank 26,5) o bucket 02 entra pela metade', () => {
    const base = hourlyPaceBase(
      3_500,
      curveWithOvernight,
      new Date(2026, 5, 5, 2, 30, 0),
    );
    // Mesma interpolação linear da hora corrente: 3000 + 500×0,5 = 3250
    expect(base).toBeCloseTo(3_500 * (3_250 / 3_500), 5);
  });

  it('às 03:00 de madrugada (rank 27 > todos) inclui TUDO → fração 1', () => {
    const base = hourlyPaceBase(
      3_500,
